css:
.pr { max-width: 62ch; }
.pr p { margin: 0 0 1em; }
.pr p:last-child { margin-bottom: 0; }
.pr ul, .pr ol { padding-left: 1.2em; margin: 0 0 1em; }
.pr li { margin-bottom: .35em; }
.pr h2 { margin: 1.6em 0 .5em; font-size: clamp(1.45rem, 1.1rem + 1.2vw, 2rem); line-height: 1.15; }
.pr h2:last-child { margin-bottom: 0; font-size: clamp(2rem, 1rem + 3.4vw, 3.8rem); line-height: 1.12; max-width: 18ch; margin-top: clamp(2.2rem, 5vw, 3.6rem); }
.pr h3 { margin: 1.2em 0 .4em; font-size: 1.25rem; }
